#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <limits.h>

typedef struct { int *data; size_t size,capacity; } Vector;
static int push(Vector *v,int value){
    if(v->size==v->capacity){
        if(v->capacity>SIZE_MAX/2)return 0;
        size_t capacity=v->capacity?v->capacity*2:1;
        if(capacity>SIZE_MAX/sizeof *v->data)return 0;
        int *next=realloc(v->data,capacity*sizeof *next);
        if(!next)return 0;
        v->data=next;v->capacity=capacity;
    }
    v->data[v->size++]=value;return 1;
}
static int erase(Vector *v,size_t position){
    if(position>=v->size)return 0;
    for(size_t i=position+1;i<v->size;++i)v->data[i-1]=v->data[i];
    --v->size;return 1;
}
static void destroy(Vector *v){free(v->data);*v=(Vector){0};}
int main(void) {
Vector v={0};int q,failed=0;if(scanf("%d",&q)!=1 || q<0 || q>128)return 1;
for(int k=0;k<q;++k){char command;if(scanf(" %c",&command)!=1){failed=1;break;}
 if(command=='P'){int x;if(scanf("%d",&x)!=1 || !push(&v,x)){failed=1;break;}}
 else if(command=='E'){size_t i;if(scanf("%zu",&i)!=1){failed=1;break;}puts(erase(&v,i)?"ДА":"НЕТ");}
 else if(command=='G'){size_t i;if(scanf("%zu",&i)!=1){failed=1;break;}if(i<v.size)printf("%d\n",v.data[i]);else puts("НЕТ");}
 else if(command=='S')printf("%zu %zu\n",v.size,v.capacity);else {failed=1;break;}}
destroy(&v);if(failed)return 1;
return 0;
}

